        scope.spawn(|| increment(right));
    });
    assert_eq!(actual, expected);
}

Use a small trait for deterministic choi:
trait Choice { fn choose_left(&self) -> bool; }
struct Fixed(bool);
impl Choice for Fixed {
    fn choose_left(&self) -> bool { self.0 }
}
struct TickParity(u64);
impl Choice for TickParity {
    fn choose_left(&self) -> bool { self.0 & 1 == 0 }
}
fn direction(source: &impl Choice) -> i32 {
    if source.choose_left() { -1 } else { 1 }
}
#[test]
fn the_rule_accepts_scripted_and_tick_sources() {
    assert_eq!(direction(&Fixed(true)), -1);
    assert_eq!(direction(&Fixed(false)), 1);
    assert_eq!(direction(&TickParity(2)), -1);
    assert_eq!(direction(&TickParity(3)), 1);
}

Prove deterministic water and heat:
#[derive(Clone, Copy, Debug, PartialEq)]
struct Cell { material: u8, temperature: i16 }
fn canonical_digest(cells: &[Cell]) -> u64 {
    let mut hash = 0xcbf29ce484222325_u64;
    for cell in cells {
        for byte in [cell.material, cell.temperature.to_le_bytes()[0],
                     cell.temperature.to_le_bytes()[1]] {
            hash ^= u64::from(byte);
            hash = hash.wrapping_mul(0x100000001b3);
        }
    }
    hash
}
#[test]
fn state_fields_affect_the_digest() {
    let a = [Cell { material: 1, temperature: 20 }];
    let b = [Cell { material: 1, temperature: 21 }];
    assert_eq!(canonical_digest(&a), canonical_digest(&a));
    assert_ne!(canonical_digest(&a), canonical_digest(&b));
}

Burn fuel without deleting its support i:
#[derive(Clone, Copy, Debug, PartialEq)]
enum Material { Wood, Ash }
struct Cell { material: Material, burning: bool, fuel: u8 }
fn burn_tick(cell: &mut Cell) {
    if !cell.burning { return; }
    cell.fuel = cell.fuel.saturating_sub(1);
    if cell.fuel == 0 {
