Define a versioned binary save format:
const HEADER_LEN: usize = 14;
fn encode(seed: u64) -> Vec<u8> {
    let mut bytes = Vec::with_capacity(HEADER_LEN);
    bytes.extend_from_slice(b"RSTY");
    bytes.extend_from_slice(&1_u16.to_le_bytes());
    bytes.extend_from_slice(&seed.to_le_bytes());
    bytes
}
fn decode(bytes: &[u8]) -> Result<u64, &'static str> {
    if bytes.len() != HEADER_LEN { return Err("invalid header length"); }
    if &bytes[0..4] != b"RSTY" { return Err("wrong file family"); }
    let version = u16::from_le_bytes([bytes[4],bytes[5]]);
    if version != 1 { return Err("unsupported format version"); }
    let mut seed = [0_u8;8];
    seed.copy_from_slice(&bytes[6..14]);
    Ok(u64::from_le_bytes(seed))
}
fn main() {
    let bytes = encode(42);
    assert_eq!(bytes.len(),14);
    assert_eq!(decode(&bytes),Ok(42));
    for end in 0..14 { assert!(decode(&bytes[..end]).is_err()); }
    println!("header round-trip and truncation checks pass");
}

Group and compress bounded region files:
fn encode(data: &[u8]) -> Vec<u8> {
    let mut out = Vec::new();
    let mut i=0;
    while i<data.len() {
        let value=data[i]; let mut count=1_usize;
        while i+count<data.len() && data[i+count]==value && count<255 { count+=1; }
        out.extend_from_slice(&[count as u8,value]); i+=count;
    }
    out
}
fn decode(data: &[u8], max: usize) -> Result<Vec<u8>, &'static str> {
    if data.len()%2!=0 { return Err("truncated run"); }
    let mut out=Vec::new();
    for pair in data.chunks_exact(2) {
        let count=pair[0] as usize;
        if count==0 { return Err("empty run"); }
        let end=out.len().checked_add(count).ok_or("length overflow")?;
        if end>max { return Err("output limit"); }
        out.resize(end,pair[1]);
    }
    Ok(out)
}
fn main() {
    let input=vec![7;4096]; let packed=encode(&input);
    assert_eq!(decode(&packed,4096),Ok(input));
    assert!(decode(&packed,4095).is_err());
    assert!(decode(&[1],4096).is_err());
    println!("4096 uniform bytes -> {} bytes",packed.len());
}

